import { supabase } from "@/utils/supabase";
import { getUserInfo } from "@/utils/userInfo";
import {
  PkRoom,
  PkAnswer,
  PkResult,
  ImportRecord,
  generateRoomCode,
} from "@/types/pk";
import { Word } from "@/types/game";

interface RoomRow {
  id: string;
  host_uuid: string;
  host_nickname: string;
  guest_uuid: string | null;
  guest_nickname: string | null;
  status: string;
  question_count: number;
  time_per_question: number;
  import_record_id: string | null;
  import_record_title: string | null;
  source_type: string;
  question_words: Array<{ spelling: string; meaning: string }>;
  spelling_ratio: number;
  host_ready: boolean;
  guest_ready: boolean;
  current_question: number;
  created_at: number;
  updated_at: number;
}

interface AnswerRow {
  room_id: string;
  question_index: number;
  question_word: string;
  correct_answer: string;
  options: string[];
  host_answer: string | null;
  host_time: number | null;
  host_score: number | null;
  guest_answer: string | null;
  guest_time: number | null;
  guest_score: number | null;
}

interface ImportRecordRow {
  id: string;
  owner_uuid: string;
  owner_nickname: string;
  title: string;
  word_count: number;
  words: Array<{ spelling: string; meaning: string }>;
  is_public: boolean;
  created_at: number;
}

function rowToRoom(row: RoomRow): PkRoom {
  return {
    id: row.id,
    hostUuid: row.host_uuid,
    hostNickname: row.host_nickname,
    guestUuid: row.guest_uuid,
    guestNickname: row.guest_nickname,
    status: row.status as PkRoom["status"],
    questionCount: row.question_count,
    timePerQuestion: row.time_per_question,
    importRecordId: row.import_record_id,
    importRecordTitle: row.import_record_title,
    sourceType: row.source_type as "import" | "random",
    questionWords: row.question_words || [],
    spellingRatio: row.spelling_ratio ?? 0,
    hostReady: row.host_ready,
    guestReady: row.guest_ready,
    currentQuestion: row.current_question,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function rowToAnswer(row: AnswerRow): PkAnswer {
  return {
    roomId: row.room_id,
    questionIndex: row.question_index,
    questionWord: row.question_word,
    correctAnswer: row.correct_answer,
    options: row.options,
    hostAnswer: row.host_answer,
    hostTime: row.host_time,
    hostScore: row.host_score,
    guestAnswer: row.guest_answer,
    guestTime: row.guest_time,
    guestScore: row.guest_score,
  };
}

function rowToImportRecord(row: ImportRecordRow): ImportRecord {
  return {
    id: row.id,
    ownerUuid: row.owner_uuid,
    ownerNickname: row.owner_nickname,
    title: row.title,
    wordCount: row.word_count,
    words: row.words,
    isPublic: row.is_public,
    createdAt: row.created_at,
  };
}

export async function uploadImportRecord(
  recordId: string,
  title: string,
  words: Word[]
): Promise<boolean> {
  const userInfo = getUserInfo();
  if (!userInfo.uuid) return false;

  try {
    const { error } = await supabase.from("import_records").upsert({
      id: recordId,
      owner_uuid: userInfo.uuid,
      owner_nickname: userInfo.nickname,
      title,
      word_count: words.length,
      words: words.map((w) => ({ spelling: w.spelling, meaning: w.meaning })),
      is_public: true,
      created_at: Date.now(),
    }, { onConflict: "id" });

    if (error) {
      console.error("上传导入记录失败:", error.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("上传导入记录异常:", e);
    return false;
  }
}

export async function fetchMyImportRecords(): Promise<ImportRecord[]> {
  const userInfo = getUserInfo();
  if (!userInfo.uuid) return [];

  try {
    const { data, error } = await supabase
      .from("import_records")
      .select("*")
      .eq("owner_uuid", userInfo.uuid)
      .order("created_at", { ascending: false })
      .limit(20);

    if (error) {
      console.error("获取导入记录失败:", error.message);
      return [];
    }
    return (data || []).map(rowToImportRecord);
  } catch (e) {
    console.error("获取导入记录异常:", e);
    return [];
  }
}

export async function fetchWaitingRooms(): Promise<PkRoom[]> {
  try {
    const { data, error } = await supabase
      .from("pk_rooms")
      .select("*")
      .eq("status", "waiting")
      .is("guest_uuid", null)
      .order("created_at", { ascending: false })
      .limit(20);

    if (error) {
      console.error("获取房间列表失败:", error.message);
      return [];
    }
    return (data || []).map(rowToRoom);
  } catch (e) {
    console.error("获取房间列表异常:", e);
    return [];
  }
}

export async function createPkRoom(params: {
  questionCount: number;
  timePerQuestion: number;
  sourceType: "import" | "random";
  importRecordId?: string;
  importRecordTitle?: string;
  questionWords: Array<{ spelling: string; meaning: string }>;
  spellingRatio?: number;
}): Promise<PkRoom | null> {
  const userInfo = getUserInfo();
  if (!userInfo.uuid) return null;

  const roomId = generateRoomCode();
  const now = Date.now();

  try {
    const { data, error } = await supabase
      .from("pk_rooms")
      .insert({
        id: roomId,
        host_uuid: userInfo.uuid,
        host_nickname: userInfo.nickname,
        guest_uuid: null,
        guest_nickname: null,
        status: "waiting",
        question_count: params.questionCount,
        time_per_question: params.timePerQuestion,
        import_record_id: params.importRecordId || null,
        import_record_title: params.importRecordTitle || null,
        source_type: params.sourceType,
        question_words: params.questionWords,
        spelling_ratio: params.spellingRatio ?? 0,
        host_ready: true,
        guest_ready: false,
        current_question: 0,
        created_at: now,
        updated_at: now,
      })
      .select()
      .limit(1);

    if (error) {
      console.error("创建房间失败:", error.message);
      return null;
    }
    if (!data || data.length === 0) return null;
    return rowToRoom(data[0]);
  } catch (e) {
    console.error("创建房间异常:", e);
    return null;
  }
}

export async function joinPkRoom(roomId: string): Promise<PkRoom | null> {
  const userInfo = getUserInfo();
  if (!userInfo.uuid) return null;

  try {
    const { data: existing, error: fetchError } = await supabase
      .from("pk_rooms")
      .select("*")
      .eq("id", roomId.toUpperCase())
      .limit(1);

    if (fetchError || !existing || existing.length === 0) {
      return null;
    }

    const room = existing[0];
    if (room.status !== "waiting") return null;
    if (room.guest_uuid && room.guest_uuid !== userInfo.uuid) return null;
    if (room.host_uuid === userInfo.uuid) return rowToRoom(room);

    const { data, error } = await supabase
      .from("pk_rooms")
      .update({
        guest_uuid: userInfo.uuid,
        guest_nickname: userInfo.nickname,
        status: "ready",
        updated_at: Date.now(),
      })
      .eq("id", roomId.toUpperCase())
      .select()
      .limit(1);

    if (error) {
      console.error("加入房间失败:", error.message);
      return null;
    }
    if (!data || data.length === 0) return null;
    return rowToRoom(data[0]);
  } catch (e) {
    console.error("加入房间异常:", e);
    return null;
  }
}

export async function fetchPkRoom(roomId: string): Promise<PkRoom | null> {
  try {
    const { data, error } = await supabase
      .from("pk_rooms")
      .select("*")
      .eq("id", roomId.toUpperCase())
      .limit(1);

    if (error || !data || data.length === 0) return null;
    return rowToRoom(data[0]);
  } catch (e) {
    console.error("获取房间异常:", e);
    return null;
  }
}

export async function updatePkRoom(
  roomId: string,
  updates: Partial<{
    status: string;
    hostReady: boolean;
    guestReady: boolean;
    currentQuestion: number;
  }>
): Promise<PkRoom | null> {
  try {
    const data: Record<string, unknown> = { updated_at: Date.now() };
    if (updates.status !== undefined) data.status = updates.status;
    if (updates.hostReady !== undefined) data.host_ready = updates.hostReady;
    if (updates.guestReady !== undefined) data.guest_ready = updates.guestReady;
    if (updates.currentQuestion !== undefined) data.current_question = updates.currentQuestion;

    const { data: result, error } = await supabase
      .from("pk_rooms")
      .update(data)
      .eq("id", roomId.toUpperCase())
      .select()
      .limit(1);

    if (error) {
      console.error("更新房间失败:", error.message);
      return null;
    }
    if (!result || result.length === 0) return null;
    return rowToRoom(result[0]);
  } catch (e) {
    console.error("更新房间异常:", e);
    return null;
  }
}

export async function deletePkRoom(roomId: string): Promise<boolean> {
  try {
    const { error } = await supabase
      .from("pk_rooms")
      .delete()
      .eq("id", roomId.toUpperCase());

    if (error) {
      console.error("删除房间失败:", error.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("删除房间异常:", e);
    return false;
  }
}

export async function submitPkAnswer(params: {
  roomId: string;
  questionIndex: number;
  questionWord: string;
  correctAnswer: string;
  options: string[];
  isHost: boolean;
  answer: string;
  time: number;
  score: number;
}): Promise<boolean> {
  try {
    const { error: upsertError } = await supabase
      .from("pk_answers")
      .upsert(
        {
          room_id: params.roomId,
          question_index: params.questionIndex,
          question_word: params.questionWord,
          correct_answer: params.correctAnswer,
          options: params.options,
        },
        { onConflict: "room_id,question_index", ignoreDuplicates: true }
      );

    if (upsertError) {
      console.error("upsert答案行失败:", upsertError.message);
    }

    const updateData: Record<string, unknown> = {};
    if (params.isHost) {
      updateData.host_answer = params.answer;
      updateData.host_time = params.time;
      updateData.host_score = params.score;
    } else {
      updateData.guest_answer = params.answer;
      updateData.guest_time = params.time;
      updateData.guest_score = params.score;
    }

    const { error: updateError } = await supabase
      .from("pk_answers")
      .update(updateData)
      .eq("room_id", params.roomId)
      .eq("question_index", params.questionIndex);

    if (updateError) {
      console.error("更新答案失败:", updateError.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("提交答案异常:", e);
    return false;
  }
}

export async function fetchPkAnswers(roomId: string): Promise<PkAnswer[]> {
  try {
    const { data, error } = await supabase
      .from("pk_answers")
      .select("*")
      .eq("room_id", roomId)
      .order("question_index", { ascending: true });

    if (error) return [];
    return (data || []).map(rowToAnswer);
  } catch (e) {
    console.error("获取答题记录异常:", e);
    return [];
  }
}

export async function savePkResult(params: {
  roomId: string;
  winnerUuid: string | null;
  winnerNickname: string | null;
  hostTotal: number;
  guestTotal: number;
  hostCorrect: number;
  guestCorrect: number;
}): Promise<boolean> {
  try {
    const { error } = await supabase.from("pk_results").upsert({
      room_id: params.roomId,
      winner_uuid: params.winnerUuid,
      winner_nickname: params.winnerNickname,
      host_total: params.hostTotal,
      guest_total: params.guestTotal,
      host_correct: params.hostCorrect,
      guest_correct: params.guestCorrect,
      finished_at: Date.now(),
    }, { onConflict: "room_id" });

    if (error) {
      console.error("保存结果失败:", error.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("保存结果异常:", e);
    return false;
  }
}

