import { X, BookOpen, Shuffle, Users } from "lucide-react";
import { PkRoom } from "@/types/pk";

interface Props {
  room: PkRoom;
  isHost: boolean;
  onClose: () => void;
  onToggleReady: () => void;
}

export function PkWaitingView({ room, isHost, onClose, onToggleReady }: Props) {
  const opponentReady = isHost ? room.guestReady : room.hostReady;
  const bothReady = room.hostReady && room.guestReady;
  const opponentNickname = isHost ? room.guestNickname : room.hostNickname;
  const myNickname = isHost ? room.hostNickname : room.guestNickname;
  const iAmReady = isHost ? room.hostReady : room.guestReady;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 flex flex-col">
      <div className="flex items-center gap-3 p-4">
        <button
          onClick={onClose}
          className="w-10 h-10 rounded-full bg-slate-800/60 border border-slate-600/50 flex items-center justify-center text-white hover:scale-105 transition-transform"
        >
          <X size={20} />
        </button>
        <h1 className="text-xl font-bold text-slate-100">房间已创建</h1>
      </div>

      <div className="flex-1 p-6 flex flex-col">
        <div className="w-full max-w-sm mx-auto flex flex-col gap-6">
          <div className="bg-slate-800/40 border border-slate-700 rounded-2xl p-4">
            <div className="flex items-center justify-between mb-3">
              <p className="text-slate-400 text-sm">规则</p>
              <p className="text-slate-300 text-sm">
                {room.questionCount} 题 · {room.timePerQuestion} 秒/题
              </p>
            </div>
            <div className="flex items-center gap-2">
              {room.sourceType === "import" ? (
                <BookOpen size={16} className="text-emerald-400" />
              ) : (
                <Shuffle size={16} className="text-emerald-400" />
              )}
              <p className="text-slate-300 text-sm truncate">
                {room.sourceType === "import"
                  ? room.importRecordTitle || "导入记录"
                  : "房主单词本"}
              </p>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div
              className={`p-4 rounded-2xl border-2 text-center transition-all ${
                iAmReady
                  ? "border-emerald-400 bg-emerald-500/20"
                  : "border-slate-700 bg-slate-800/40"
              }`}
            >
              <div className="w-12 h-12 mx-auto rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center mb-2">
                <span className="text-white font-bold">
                  {myNickname?.slice(0, 1)}
                </span>
              </div>
              <p className="text-slate-100 font-medium text-sm truncate">
                {myNickname}
              </p>
              <p className={`text-xs mt-1 ${iAmReady ? "text-emerald-300" : "text-slate-500"}`}>
                {iAmReady ? "已准备" : "未准备"}
              </p>
            </div>

            <div
              className={`p-4 rounded-2xl border-2 text-center transition-all ${
                opponentReady
                  ? "border-emerald-400 bg-emerald-500/20"
                  : "border-slate-700 bg-slate-800/40"
              }`}
            >
              <div className="w-12 h-12 mx-auto rounded-full bg-gradient-to-br from-cyan-500 to-teal-600 flex items-center justify-center mb-2">
                <span className="text-white font-bold">
                  {opponentNickname?.slice(0, 1) || "?"}
                </span>
              </div>
              <p className="text-slate-100 font-medium text-sm truncate">
                {opponentNickname || "等待匹配..."}
              </p>
              <p className={`text-xs mt-1 ${opponentReady ? "text-emerald-300" : "text-slate-500"}`}>
                {!opponentNickname ? "" : opponentReady ? "已准备" : "未准备"}
              </p>
            </div>
          </div>

          {!opponentNickname && (
            <div className="flex items-center justify-center gap-2 text-slate-400 text-sm py-2">
              <Users size={16} className="animate-pulse" />
              正在等待另一位玩家加入...
            </div>
          )}

          <button
            onClick={onToggleReady}
            disabled={!opponentNickname}
            className={`w-full py-4 font-bold text-lg rounded-2xl shadow-lg hover:scale-105 active:scale-95 transition-all disabled:opacity-40 disabled:hover:scale-100 flex items-center justify-center gap-2 ${
              iAmReady
                ? "bg-gradient-to-r from-amber-500 to-orange-500 text-white"
                : "bg-gradient-to-r from-emerald-500 to-teal-500 text-white"
            }`}
          >
            {iAmReady ? "取消准备" : "准备"}
          </button>

          {bothReady && (
            <p className="text-center text-emerald-400 text-sm animate-pulse">
              双方已准备，游戏即将开始…
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
