import { useState, useEffect, useCallback, useRef } from "react";
import { fetchPkAnswers, getPkRoomChannel } from "@/utils/pkApi";
import { PkAnswer } from "@/types/pk";

export function usePkAnswers(roomId: string, pollInterval = 4000) {
  const [answers, setAnswers] = useState<PkAnswer[]>([]);
  const pollIntervalRef = useRef(pollInterval);
  const loadingRef = useRef(false);

  useEffect(() => {
    pollIntervalRef.current = pollInterval;
  }, [pollInterval]);

  const refresh = useCallback(async () => {
    if (!roomId || loadingRef.current) return;
    loadingRef.current = true;
    try {
      const list = await fetchPkAnswers(roomId);
      setAnswers(list);
    } finally {
      loadingRef.current = false;
    }
  }, [roomId]);

  useEffect(() => {
    if (!roomId) return;

    loadingRef.current = false;
    refresh();

    const channel = getPkRoomChannel(roomId);

    channel.on(
      "broadcast",
      { event: "answer" },
      () => {
        refresh();
      }
    );

    channel.subscribe();

    const pollTimer = window.setInterval(refresh, pollIntervalRef.current);

    return () => {
      channel.unsubscribe();
      clearInterval(pollTimer);
    };
  }, [roomId, refresh]);

  return { answers, setAnswers, refresh };
}
