import { useState, useEffect, useCallback, useRef } from "react";
import {
  fetchPkRoom,
  getPkRoomChannel,
} from "@/utils/pkApi";
import { PkRoom } from "@/types/pk";

export function usePkRoom(
  roomId: string,
  options?: {
    onDeleted?: () => void;
    pollInterval?: number;
  }
) {
  const [room, setRoom] = useState<PkRoom | null>(null);
  const onDeletedRef = useRef<(() => void) | undefined>(undefined);
  const pollIntervalRef = useRef<number>(2000);
  const consecutiveFailuresRef = useRef(0);
  const deletedRef = useRef(false);
  const lastUpdatedAtRef = useRef<number>(0);

  useEffect(() => {
    onDeletedRef.current = options?.onDeleted;
    pollIntervalRef.current = options?.pollInterval ?? 2000;
  }, [options]);

  const refresh = useCallback(async () => {
    if (!roomId || deletedRef.current) return;
    try {
      const r = await fetchPkRoom(roomId);
      if (!r) {
        consecutiveFailuresRef.current += 1;
        if (consecutiveFailuresRef.current >= 5) {
          deletedRef.current = true;
          onDeletedRef.current?.();
        }
        return;
      }
      consecutiveFailuresRef.current = 0;
      if (r.updatedAt !== lastUpdatedAtRef.current) {
        lastUpdatedAtRef.current = r.updatedAt;
        setRoom(r);
      }
    } catch {
      consecutiveFailuresRef.current += 1;
      if (consecutiveFailuresRef.current >= 5) {
        deletedRef.current = true;
        onDeletedRef.current?.();
      }
    }
  }, [roomId]);

  useEffect(() => {
    if (!roomId) return;

    deletedRef.current = false;
    consecutiveFailuresRef.current = 0;
    lastUpdatedAtRef.current = 0;

    refresh();

    const channel = getPkRoomChannel(roomId);

    channel.on(
      "postgres_changes",
      { event: "UPDATE", schema: "public", table: "pk_rooms", filter: `id=eq.${roomId}` },
      (payload: { new: Record<string, unknown> }) => {
        const row = payload.new;
        const newUpdatedAt = row.updated_at as number;
        if (newUpdatedAt === lastUpdatedAtRef.current) return;
        lastUpdatedAtRef.current = newUpdatedAt;
        setRoom({
          id: row.id as string,
          hostUuid: row.host_uuid as string,
          hostNickname: row.host_nickname as string,
          guestUuid: row.guest_uuid as string | null,
          guestNickname: row.guest_nickname as string | null,
          status: row.status as PkRoom["status"],
          questionCount: row.question_count as number,
          timePerQuestion: row.time_per_question as number,
          importRecordId: row.import_record_id as string | null,
          importRecordTitle: row.import_record_title as string | null,
          sourceType: row.source_type as "import" | "random",
          questionWords: (row.question_words as Array<{ spelling: string; meaning: string }>) || [],
          spellingRatio: (row.spelling_ratio as number) ?? 0,
          hostReady: row.host_ready as boolean,
          guestReady: row.guest_ready as boolean,
          currentQuestion: row.current_question as number,
          createdAt: row.created_at as number,
          updatedAt: newUpdatedAt,
        });
      }
    );

    channel.on(
      "postgres_changes",
      { event: "DELETE", schema: "public", table: "pk_rooms", filter: `id=eq.${roomId}` },
      () => {
        if (deletedRef.current) return;
        deletedRef.current = true;
        onDeletedRef.current?.();
      }
    );

    channel.subscribe();

    const pollTimer = window.setInterval(refresh, pollIntervalRef.current);

    return () => {
      channel.unsubscribe();
      clearInterval(pollTimer);
    };
  }, [roomId, refresh]);

  return { room, setRoom, refresh };
}
