import { PartyPopper, Coins, ArrowRight } from "lucide-react";
import { useGameStore } from "@/store/useGameStore";

interface WinModalProps {
  open: boolean;
}

export default function WinModal({ open }: WinModalProps) {
  const level = useGameStore((s) => s.level);
  const nextLevel = useGameStore((s) => s.nextLevel);

  if (!open) return null;

  const reward = 2 + level;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-yellow-500/30 rounded-3xl p-8 sm:p-10 max-w-md w-full shadow-2xl text-center">
        <div className="absolute -top-6 left-1/2 -translate-x-1/2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-yellow-400 to-orange-500 flex items-center justify-center shadow-lg shadow-yellow-500/50">
            <PartyPopper className="text-white" size={24} />
          </div>
        </div>

        <h2 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 via-orange-400 to-pink-500 mb-3 mt-4">
          第 {level} 关通过！
        </h2>

        <div className="flex items-center justify-center gap-2 mb-6 bg-amber-500/20 rounded-full px-5 py-3 mx-auto w-fit border border-amber-400/30">
          <span className="text-amber-300">获得</span>
          <Coins size={20} className="text-amber-400" />
          <span className="text-amber-300 font-bold text-xl">+{reward}</span>
        </div>

        <p className="text-slate-400 mb-6">
          太棒了！准备好挑战下一关了吗？
        </p>

        <button
          onClick={nextLevel}
          className="w-full flex items-center justify-center gap-2 py-3.5 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white font-bold rounded-xl transition-all shadow-lg shadow-emerald-500/30 hover:shadow-emerald-500/50"
        >
          进入第 {level + 1} 关
          <ArrowRight size={20} />
        </button>
      </div>
    </div>
  );
}
