import { X, Check, AlertCircle, User, Gamepad2 } from "lucide-react";

interface MigrateImportData {
  userInfo: { uuid: string; nickname: string };
  gameData?: { level?: number; score?: number; coins?: number };
  wordData?: { words?: unknown[]; wrongWords?: unknown[]; currentLevel?: number; quizSessionsLeft?: number };
  bestScore?: number;
}

interface MigrateModalProps {
  open: boolean;
  importData: MigrateImportData | null;
  onClose: () => void;
  onConfirm: () => void;
}

export default function MigrateModal({ open, importData, onClose, onConfirm }: MigrateModalProps) {
  if (!open || !importData) return null;

  const { userInfo, gameData, wordData, bestScore } = importData;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={onClose} />
      <div className="relative bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 border border-amber-500/30 rounded-3xl p-6 sm:p-8 max-w-sm w-full shadow-2xl flex flex-col max-h-[85vh]">
        <div className="flex items-center justify-between mb-4 shrink-0">
          <h2 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-amber-400 via-orange-400 to-red-400">
            迁移用户数据
          </h2>
          <button
            onClick={onClose}
            className="p-1 rounded-lg hover:bg-slate-700/50 transition-all"
          >
            <X size={20} className="text-slate-400" />
          </button>
        </div>

        <div className="flex flex-col gap-4 overflow-y-auto min-h-0 flex-1">
          <div className="flex items-start gap-3 p-3 bg-amber-500/10 border border-amber-500/30 rounded-xl">
            <AlertCircle size={20} className="text-amber-400 shrink-0 mt-0.5" />
            <div>
              <p className="text-amber-200 text-sm font-medium mb-1">检测到迁移请求</p>
              <p className="text-slate-400 text-xs">
                您正在从旧客户端迁移数据到新客户端。迁移后将覆盖当前用户数据。
              </p>
            </div>
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-4 py-3 border border-slate-700/50">
            <p className="text-slate-400 text-xs mb-2">用户信息</p>
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                <User size={14} className="text-violet-400 shrink-0" />
                <span className="text-slate-300 text-sm">昵称</span>
              </div>
              <div className="text-slate-400 text-xs pl-6">
                {userInfo.nickname}
              </div>
              <div className="flex items-center gap-2">
                <Gamepad2 size={14} className="text-sky-400 shrink-0" />
                <span className="text-slate-300 text-sm">UUID</span>
              </div>
              <div className="text-slate-400 text-xs pl-6 break-all">
                {userInfo.uuid}
              </div>
            </div>
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-4 py-3 border border-slate-700/50">
            <p className="text-slate-400 text-xs mb-2">游戏数据</p>
            <ul className="space-y-1.5">
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>关卡: {gameData?.level || 1}</span>
              </li>
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>分数: {gameData?.score || 0}</span>
              </li>
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>金币: {gameData?.coins || 0}</span>
              </li>
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>最高分: {bestScore || 0}</span>
              </li>
            </ul>
          </div>

          <div className="bg-slate-800/50 rounded-2xl px-4 py-3 border border-slate-700/50">
            <p className="text-slate-400 text-xs mb-2">单词数据</p>
            <ul className="space-y-1.5">
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>单词数量: {wordData?.words?.length || 0}</span>
              </li>
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>错题本: {wordData?.wrongWords?.length || 0}</span>
              </li>
              <li className="flex items-center gap-2 text-slate-300 text-sm">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span>答题次数: {wordData?.quizSessionsLeft || 2}</span>
              </li>
            </ul>
          </div>
        </div>

        <div className="flex gap-3 mt-4 shrink-0">
          <button
            onClick={onClose}
            className="flex-1 py-3 bg-slate-700/50 hover:bg-slate-600/50 text-slate-300 rounded-xl transition-all border border-slate-600/50"
          >
            取消
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 py-3 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-white rounded-xl transition-all font-medium shadow-lg shadow-amber-500/30"
          >
            确认迁移
          </button>
        </div>
      </div>
    </div>
  );
}